KG42.register("clusters-2be97d6270c1b11f9e2b686b",{"id":"46-commercial_building_transactive_control::v142-d-K007","paper":"46-commercial_building_transactive_control","label":"Baseline setpoint fallback when RTU has no supply-demand intersection","record":{"cluster_id":"v142-d-K007","label":"Baseline setpoint fallback when RTU has no supply-demand intersection","market_meaning":"In the RTU real-time price or load-following service, when the supply and demand curves have no intersection, set the cooling setpoint to the named baseline setpoint; the structural representation of the baseline definition and conditions remains incomplete.","mechanism_ids":["v141-a-M02"],"market_types":["DEM","LEM"],"process_stages":["coordination","bidding"],"scope_disposition":"conditional","scope_explanation":"The fallback applies only to the real-time price and load-following services described by the source; shared R011 only indicates the supply-configuration background under the same services, does not claim that it directly calculates the setpoint, and does not extend the fallback to demand limiting.","assembly_status":"partial","boundary_rationale":"The setpoint selection triggered by the no-intersection condition is an independent operational decision, retaining a conditional link to supply configuration; the missing RTU demand and clearing processes cannot be filled in by central-system rules.","chain_bindings":[{"chain_id":"v141-c-R010","ownership":"primary","role":"core","rationale":"Primary responsibility for the baseline setpoint fallback when the two RTU services have no intersection."},{"chain_id":"v141-c-R011","ownership":"shared","role":"context","rationale":"Provides only the supply-configuration background for real-time price and load following, and does not supplement it into a direct dependency from supply curve to setpoint."}],"connections":[{"connection_id":"v142-d-K007-L01","from_chain_id":"v141-c-R011","to_chain_id":"v141-c-R010","kind":"complementary_scope","from_refs":["v141-c-R011::phi::v141-c-R011-C001","v141-c-R011::phi::v141-c-R011-C003"],"to_refs":["v141-c-R010::phi::v141-c-R010-C001"],"evidence_ids":["ev-v141-b-g03-011","ev-v141-b-g03-012"],"rationale":"The same RTU configuration scope separately describes the supply updates and no-intersection fallback of the two service types; this is only complementarity in service conditions, and the intermediate process of intersection determination and setpoint calculation is still not provided by the existing Rule-Chains."}],"object_mappings":[],"gaps":[{"gap_id":"v142-d-K007-G01","category":"upstream_missing","description":"The M02 evidence names the baseline setpoint, but its detailed definition, units, values, and per-zone or per-period indices remain unresolved; the M01 definition cannot be transplanted by means of the same symbol.","chain_ids":["v141-c-R010"],"object_refs":["v141-c-R010::x::T_set","v141-c-R010::theta::T_set,base"],"evidence_ids":["ev-v141-b-g03-012"],"proposal_ids":[],"required_work":"Supplement the setpoint and baseline definitions under the same mechanism in M02; units, values, and indices not supported by the source remain blank."},{"gap_id":"v142-d-K007-G02","category":"upstream_missing","description":"The existing M02 Rule-Chain does not freeze the interfaces for demand generation, intersection determination, or clearing results; the relevant Eqs. (10)–(11) exist only in the evidence catalog and cannot be supplemented by D into a Rule-Chain.","chain_ids":["v141-c-R010","v141-c-R011"],"object_refs":["v141-c-R010::phi::v141-c-R010-C001","v141-c-R010::V::coordination.price_signal","v141-c-R011::V::bidding.supply"],"evidence_ids":["v141-b-g01-e12","v141-b-g02-E019","v141-b-g02-E020","ev-v141-b-g03-012"],"proposal_ids":[],"required_work":"Extract the RTU demand and clearing Rule-Chains upstream by C, and clarify the source of the no-intersection condition and the structural interface; neither M01 nor the M03 clearing interface limited to the central-system scope may be regarded as covering the RTU process."},{"gap_id":"v142-d-K007-G03","category":"unverified_source","description":"The evidence for the RTU fallback and service configuration both remains unverified, and there is currently no independent source audit or scientific acceptance conclusion.","chain_ids":["v141-c-R010","v141-c-R011"],"object_refs":[],"evidence_ids":["ev-v141-b-g03-011","ev-v141-b-g03-012"],"proposal_ids":[],"required_work":"Subsequently verify the RTU scope of application, the original sentence on no intersection, and the baseline definition, then handle upstream supplementation."}]},"rule_refs":["46-commercial_building_transactive_control::v141-c-R010","46-commercial_building_transactive_control::v141-c-R011"],"unresolved_rule_refs":[],"node_ids":["COMP-c619c76070af37df","COMP-e1497473e57dc523"]});
